     * @param {Array} [args]
     * @return {Array}
     */
    emit(eventName, args = []) {
        const callbacks = this.events.get(eventName);
        if (!callbacks || callbacks.length === 0) {
            return [];
        }
        return callbacks.map(cb => cb(...args));
    }
}
